    <script>
        // 自动获取酒馆角色头像并应用
        (function() {
            // 尝试从酒馆获取角色头像URL
            function applyCharacterAvatar() {
                const avatarElement = document.querySelector('.selian-avatar.char-avatar');
                if (!avatarElement) return;

                // 方法1: 从酒馆的avatar_url获取
                if (typeof avatar_url !== 'undefined' && avatar_url) {
                    avatarElement.style.backgroundImage = `url('${avatar_url}')`;
                    return;
                }

                // 方法2: 从页面中已存在的角色头像获取
                const existingAvatar = document.querySelector('#chat .mes[is_user="false"] .avatar img');
                if (existingAvatar && existingAvatar.src) {
                    avatarElement.style.backgroundImage = `url('${existingAvatar.src}')`;
                    return;
                }

                // 方法3: 尝试从SillyTavern的characters数据获取
                if (typeof characters !== 'undefined' && typeof this_chid !== 'undefined') {
                    const char = characters[this_chid];
                    if (char && char.avatar) {
                        const avatarPath = `/characters/${char.avatar}`;
                        avatarElement.style.backgroundImage = `url('${avatarPath}')`;
                        return;
                    }
                }

                // 方法4: 使用通用的角色头像路径模式
                const charName = '{{char}}';
                if (charName && charName !== '{{char}}') {
                    avatarElement.style.backgroundImage = `url('/characters/${encodeURIComponent(charName)}/avatar.png')`;
                }
            }

            // 页面加载完成后执行
            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', applyCharacterAvatar);
            } else {
                applyCharacterAvatar();
            }

            // 延迟重试一次，确保酒馆数据加载完成
            setTimeout(applyCharacterAvatar, 500);
        })();
    </script>
